(() => {
  const C = window.COURSE;
  const tg = window.Telegram?.WebApp;
  const ASSET = 'presentation/assets/';
  const app = document.getElementById('app');
  const stateKey = 'chs-platform-v1';
  const seedState = () => ({institutions:[{id:'him-001',name:'Hotel Institute Montreux'}],editions:[{id:'future-of-hospitality-2026',courseId:C.id,year:C.edition,status:'ACTIVE'}],licenses:[{id:'license-him-2026',institutionId:'him-001',editionId:'future-of-hospitality-2026',startDate:'2026-09-01',endDate:'2027-08-31',studentLimit:100,status:'ACTIVE'}],enrollments:[],progress:{},submissions:[],quizzes:{},licenseActive:true});
  const getState = () => { try { return {...seedState(),...(JSON.parse(localStorage.getItem(stateKey))||{})}; } catch { return seedState(); } };
  const saveState = s => localStorage.setItem(stateKey, JSON.stringify(s));
  const ensureEnrollment = profile => {if(profile.role!=='STUDENT')return;const s=getState();if(!s.enrollments.some(x=>x.studentEmail===profile.email&&x.courseId===C.id&&x.edition===C.edition)){s.enrollments.push({id:`enrol-${Date.now()}`,studentEmail:profile.email,institutionId:profile.institutionId||'him-001',courseId:C.id,edition:C.edition,status:'ACTIVE',startedAt:new Date().toISOString()});saveState(s)}};
  let state = getState();
  let toastTimer;
  const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const user = () => { try { return JSON.parse(sessionStorage.getItem('chs-user')); } catch { return null; } };
  const key = () => `${user()?.email || 'guest'}:${C.id}:${C.edition}`;
  const progressFor = () => state.progress[key()] || [];
  const allLessons = C.modules.flatMap(m => m.lessons.map(l => ({...l,module:m,thumbnail:l.thumbnail||m.image,videoUrl:l.videoUrl||null})));
  const completeCount = () => progressFor().length;
  const pct = () => Math.round(completeCount() / allLessons.length * 100);
  const certificateReady = () => pct()===100 && state.submissions.some(s=>s.student===user()?.email&&s.courseId===C.id&&s.edition===C.edition&&s.status==='APPROVED');
  const initials = name => (name || 'ET').split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase();
  const route = () => { const raw = location.hash.replace(/^#\/?/, ''); return raw ? raw.split('?')[0].split('/') : ['']; };
  const go = path => { location.hash = '/' + path.replace(/^\//,''); };
  function syncTelegramNavigation(){if(!tg?.BackButton)return;const [page,sub]=route();if(page&&page!=='dashboard')tg.BackButton.show();else tg.BackButton.hide()}
  if(tg){tg.ready();tg.expand();document.documentElement.classList.add('telegram-webapp');tg.setHeaderColor?.('#f5f4f0');tg.setBackgroundColor?.('#f5f4f0');const syncViewport=()=>document.documentElement.style.setProperty('--tg-viewport-height',`${tg.viewportHeight||window.innerHeight}px`);syncViewport();tg.onEvent?.('viewportChanged',syncViewport);tg.BackButton?.onClick(()=>{const [page,sub]=route();if(page==='lesson')go(`module/${sub}`);else if(page==='review')go('instructor');else if(page==='login')go('');else if(page==='module')go('course');else if(page==='dashboard'||!page)tg.close?.();else if(['course','cases','progress','profile','updates','assignment','quiz','certificate','search'].includes(page))go(user()?.role==='INSTRUCTOR'?'instructor':user()?.role==='ADMIN'?'admin':'dashboard');else tg.close?.()})}
  const image = (name, alt='', cls='') => `<img class="${cls}" src="${ASSET}${esc(name)}" alt="${esc(alt)}" loading="lazy">`;
  const button = (label, path, cls='') => `<a class="button ${cls}" href="#/${path}">${label}<span aria-hidden="true">↗</span></a>`;
  const moduleProgress = m => Math.round(m.lessons.filter(l=>progressFor().includes(l.id)).length/m.lessons.length*100);
  const demoUser = (role='student') => {
    const presets={student:{name:'Alex Morgan',email:'student@him.edu',role:'STUDENT'},instructor:{name:'Egor Tarasenko',email:'instructor@him.edu',role:'INSTRUCTOR'},admin:{name:'HIM Administrator',email:'admin@him.edu',role:'ADMIN'}};
    const profile={...presets[role],institutionId:'him-001'};sessionStorage.setItem('chs-user',JSON.stringify(profile));ensureEnrollment(profile);go(role==='student'?'dashboard':role==='instructor'?'instructor':'admin');
  };
  const header = (publicPage=false) => {
    const u=user();
    if(publicPage) return `<header class="site-header"><a class="brand" href="#/"><span class="brand-mark">HIM</span><span>HIM <span style="color:var(--muted)">×</span> EGOR TARASENKO</span></a><nav class="nav" aria-label="Main navigation"><a class="nav-link" href="#/" data-scroll="explore">THE ELECTIVE</a><a class="nav-link" href="#/" data-scroll="author">THE AUTHOR</a><a class="nav-link" href="#/" data-scroll="cases">CASES</a><a class="button small" href="#/login">STUDENT LOGIN <span>↗</span></a></nav></header>`;
    const role=u?.role;
    const links=role==='INSTRUCTOR'?[['Overview','instructor'],['Submissions','instructor'],['Analytics','instructor']]:role==='ADMIN'?[['Overview','admin'],['Institutions','admin'],['Analytics','admin']]:[['Home','dashboard'],['Course','course'],['Cases','cases'],['Progress','progress']];
    return `<header class="app-header"><a class="brand" href="#/${role==='STUDENT'?'dashboard':role==='INSTRUCTOR'?'instructor':'admin'}"><span class="brand-mark">HIM</span><span>HIM <span style="color:var(--muted)">×</span> EGOR</span></a><nav class="app-nav" aria-label="Application navigation">${links.map(([t,p])=>`<a href="#/${p}">${t}</a>`).join('')}<button class="nav-link" data-action="search">SEARCH⌕</button></nav><div class="user-chip"><span>${esc(u?.name || 'Guest')}</span><span class="avatar">${initials(u?.name)}</span><button class="nav-link" data-action="profile">PROFILE</button>${role!=='STUDENT'?'<button class="nav-link" data-action="logout">SIGN OUT</button>':''}</div></header>`;
  };
  const bottomNav = () => {const role=user()?.role;const links=role==='INSTRUCTOR'?[['Overview','instructor','⌂'],['Submissions','instructor','▤'],['Search','search','⌕'],['Profile','profile','◯']]:role==='ADMIN'?[['Overview','admin','⌂'],['Institutions','admin','▤'],['Search','search','⌕'],['Profile','profile','◯']]:[['Home','dashboard','⌂'],['Course','course','▤'],['Progress','progress','◌'],['Search','search','⌕'],['Profile','profile','◯']];return `<nav class="mobile-bottom" aria-label="Mobile navigation">${links.map(([t,p,i])=>p==='search'?`<button data-action="search"><span>${i}</span>${t}</button>`:`<a href="#/${p}"><span>${i}</span>${t}</a>`).join('')}</nav>`};
  const layout = (content, publicPage=false) => `${publicPage?header(true):header()}${content}${publicPage?`<footer class="footer"><span>© ${new Date().getFullYear()} EGOR TARASENKO · COURSE CONTENT</span><span>HIM × THE FUTURE OF HOSPITALITY · ${C.edition} EDITION</span></footer>`:bottomNav()}`;

  function landing(){
    const c=C;
    return layout(`<main>
      <section class="hero shell"><div class="hero-copy"><span class="eyebrow">A DIGITAL ELECTIVE · HIM × EGOR TARASENKO</span><h1><span>THE FUTURE</span><span><em>OF</em> HOSPITALITY</span></h1><p>A digital elective about how hospitality is changing — and what comes next.</p><div class="hero-actions"><a class="button" href="#/course">EXPLORE THE COURSE <span>↗</span></a><a class="button text" href="#/login">STUDENT LOGIN <span>→</span></a></div></div><div class="hero-media">${image('horeca-interior-design.jpg','An atmospheric contemporary hotel bar, warm lighting and considered materials')}<span class="meta hero-index">2026 EDITION · 01 / 09</span><span class="image-caption meta">THE ROOM SETS THE TONE</span></div></section>
      <div class="intro-strip"><span class="eyebrow">A LIVING DIGITAL ELECTIVE</span><strong>Education for an industry that never stands still.</strong><span class="meta">2026 → 2027 → 2028</span></div>
      <section class="section shell" id="why"><div class="section-head"><div><span class="eyebrow">01 — WHY THIS ELECTIVE</span><h2>Hospitality is<br>always becoming.</h2></div><p>Traditional education cannot update itself at the pace of the industry. This elective brings current thinking, emerging tools and real-world cases into one evolving learning experience.</p></div><div class="why-grid"><div class="why-big">The next generation of hospitality will be shaped by the way we connect people, place and possibility.</div><div class="why-note"><p>Explore the intersection of hospitality, technology, design, neuroscience, food & beverage and entrepreneurship.</p><span class="meta">Learn from the industry. Think beyond the obvious.</span></div></div></section>
      <section class="section shell" id="explore"><div class="section-head"><div><span class="eyebrow">02 — WHAT YOU WILL EXPLORE</span><h2>Ideas with<br>an industry edge.</h2></div><p>Nine connected modules. A point of view on the forces reshaping hospitality — and the space to develop your own.</p></div><div class="discipline-grid">${['Hospitality Futures','Experience Design','Neurogastronomy','Restaurant & Bar Concepts','AI & Automation','Hospitality Technology','Food & Beverage Futures','Entrepreneurship'].map((x,i)=>`<a class="discipline" href="#/course"><span class="number">${String(i+1).padStart(2,'0')}</span><h3>${x}</h3></a>`).join('')}</div></section>
      <section class="section shell"><div class="section-head"><div><span class="eyebrow">03 — HOW IT WORKS</span><h2>From insight<br>to intention.</h2></div><p>A considered learning journey: absorb an idea, test it against the industry, then apply it to a concept of your own.</p></div><div class="steps">${[['01','Learn','Ideas, principles and new perspectives.'],['02','Explore','Real industry cases and references.'],['03','Apply','Connect thinking to your own concept.'],['04','Submit','Share a considered piece of work.'],['05','Feedback','Receive human, actionable review.'],['06','Build','Bring it together in your final project.']].map(a=>`<div class="step"><span class="number">${a[0]}</span><h3>${a[1]}</h3><p>${a[2]}</p></div>`).join('')}</div></section>
      <section class="section shell" id="cases"><div class="section-head"><div><span class="eyebrow">04 — REAL INDUSTRY CASES</span><h2>Look closer.<br>Learn from practice.</h2></div><p>Editorial case files turn current hospitality practice into material for discussion, analysis and action.</p></div><div class="case-feature">${image(C.cases[0].image,'A considered bar interior with a warm, tactile atmosphere')}<div class="case-feature-copy"><span class="eyebrow">CASE FILE · HONG KONG</span><h3>Bar Leone</h3><p>What happens when a bar puts the familiar, the generous and the unpretentious at the centre of its proposition?</p><a href="#/cases" class="button text">EXPLORE THE CASES <span>→</span></a></div></div><div class="case-list">${C.cases.slice(1).map(x=>`<article class="case-item">${image(x.image,x.title)}<span class="meta">${esc(x.location)} · ${esc(x.industry)}</span><h3>${esc(x.title)}</h3><p>${esc(x.takeaway)}</p></article>`).join('')}</div></section>
      <section class="section shell" id="author"><div class="section-head"><div><span class="eyebrow">05 — THE AUTHOR</span><h2>EGOR<br>TARASENKO</h2></div><p>HIM alumnus · Master in Business Management<br><br>Created by a hospitality practitioner and HIM graduate, this elective brings lived industry experience into an academic framework.</p></div><div class="timeline"><div class="timeline-aside">A PRACTICE-LED<br>POINT OF VIEW</div><div class="timeline-list">${[['EDUCATION','Hotel Institute Montreux','Master in Business Management'],['HOSPITALITY','Crowne Plaza St. Petersburg','Foundations in hotel operations'],['INTERNATIONAL','Jumeirah Beach Hotel Dubai','A global perspective on guest experience'],['ENTREPRENEURSHIP','Hospitality entrepreneurship','From an idea to a working concept'],['CONCEPTS','Restaurant & bar concepts','Positioning, experience and operations'],['TECHNOLOGY','Hospitality technology','Tools in service of better hospitality'],['TODAY','Current projects','Building the next generation of hospitality education']].map(a=>`<div class="timeline-row"><span class="meta">${a[0]}</span><span><strong>${a[1]}</strong><br><span>${a[2]}</span></span></div>`).join('')}</div></div></section>
      <section class="section shell"><div class="section-head"><div><span class="eyebrow">06 — COURSE STRUCTURE</span><h2>Nine modules.<br>One connected journey.</h2></div><p>Move from the signals shaping the industry to a final concept grounded in your own point of view.</p></div><div class="module-preview">${C.modules.map(m=>`<a class="module-row" href="#/course"><span class="module-num">${m.number}</span><div><h3>${esc(m.title)}</h3><p>${esc(m.description)}</p></div><span class="meta module-meta">${m.lessons.length} LEARNING UNIT</span><span>↗</span></a>`).join('')}</div></section>
      <section class="section shell"><div class="final-banner"><div><span class="eyebrow">THE FINAL PROJECT</span><h2 class="page-title">DESIGN THE HOSPITALITY CONCEPT OF TOMORROW.</h2></div><div><p>Imagine you are building a hospitality concept for 2030. Define its audience, experience, space, food & beverage, technology, business model and visual direction.</p><a class="button" href="#/course">VIEW THE ELECTIVE <span>↗</span></a></div></div></section>
      <section class="cta-band"><h2>Stay curious about what comes next.</h2><a class="button" href="#/login">START THE ELECTIVE <span>↗</span></a></section>
    </main>`,true);
  }
  function login(){if(tg)return `<main class="app-main"><div class="page-head"><div><span class="eyebrow">TELEGRAM MINI APP · SIGN-IN</span><h1 class="page-title">ACCESS COULD<br>NOT BE VERIFIED.</h1><p>Close this page and reopen the elective from the Telegram bot. If the issue continues, ask the administrator to check the BotHost configuration.</p></div><a class="button" href="#/">RETURN TO HOME <span>↗</span></a></div></main>`;return `<main class="login-page"><div class="login-visual">${image('horeca-chefs-counter.jpg','A chef at work in an open kitchen')}<div class="login-visual-copy"><span class="eyebrow" style="color:#fff">HIM × EGOR TARASENKO</span><h1>The Future<br>of Hospitality</h1><p>A digital elective exploring the ideas, technologies and experiences shaping the next generation of hospitality.</p></div></div><div class="login-form-wrap"><form class="login-form" id="login-form"><span class="eyebrow">STUDENT ACCESS · ${C.edition} EDITION</span><h2>Welcome back.</h2><p>Sign in to continue your learning journey.</p><div class="field"><label for="email">Email address</label><input class="form-control" id="email" name="email" type="email" autocomplete="username" required placeholder="name@institution.edu"></div><div class="field"><label for="password">Password</label><input class="form-control" id="password" name="password" type="password" autocomplete="current-password" required placeholder="Enter your password"></div><p id="login-error" class="form-help" role="alert"></p><button class="button" type="submit" style="width:100%">SIGN IN <span>↗</span></button><div class="demo-access"><span class="eyebrow">DEMO ACCESS</span><p>Explore the working product flows with a local demo profile. No account setup required.</p><div class="demo-buttons"><button type="button" data-role="student">DEMO STUDENT</button><button type="button" data-role="instructor">INSTRUCTOR</button><button type="button" data-role="admin">ADMIN</button></div><p>Demo identities: student@him.edu · instructor@him.edu · admin@him.edu</p></div><a href="#/" class="button text" style="margin-top:18px">← BACK TO THE ELECTIVE</a></form></div></main>`;}
  function dashboard(){const u=user();const next=allLessons.find(x=>!progressFor().includes(x.id))||allLessons[0];const submission=state.submissions.filter(s=>s.student===u.email&&s.courseId===C.id&&s.edition===C.edition).at(-1);const fb=submission?.feedback;return layout(`<main class="app-main"><div class="welcome"><div><span class="eyebrow">YOUR LEARNING SPACE · ${C.edition} EDITION</span><h1>WELCOME BACK,<br>${esc((u.name.split(' ')[0]||'STUDENT').toUpperCase())}.</h1><p>A considered journey through what hospitality can become.</p></div><span class="edition-tag meta">HOTEL INSTITUTE MONTREUX · ${C.edition}</span></div><div class="dashboard-grid"><section class="resume-panel"><div class="resume-copy"><span class="eyebrow" style="color:#ccc">CONTINUE YOUR ELECTIVE</span><h2>${esc(next.module.title)}</h2><p>${esc(next.title)} · ${next.duration}</p><div class="progress-ring" aria-label="${pct()} percent course progress"><span>${pct()}%<small>COMPLETE</small></span></div>${button(progressFor().includes(next.id)?'REVISIT LESSON':'CONTINUE LEARNING',`lesson/${next.module.id}/${next.id}`,'small')}</div>${image(next.module.image,next.module.title,'resume-image')}</section><aside class="side-stats"><div class="stat-panel"><span class="meta">COURSE PROGRESS</span><strong>${pct()}%</strong><div class="bar"><span style="width:${pct()}%"></span></div></div><div class="stat-panel"><span class="meta">LESSONS COMPLETED</span><strong>${completeCount()} <small style="font:14px var(--sans);color:var(--muted)">/ ${allLessons.length}</small></strong><p>2026 edition</p></div><div class="stat-panel"><span class="meta">CURRENT MODULE</span><strong style="font-size:23px">${next.module.number} <span class="serif">${esc(next.module.title)}</span></strong><p>${next.module.lessons[0].duration} · next lesson</p></div></aside></div><div class="dash-lower"><section class="dash-section"><h2>YOUR COURSE</h2><div class="simple-list">${C.modules.slice(0,4).map(m=>`<a class="simple-row" href="#/module/${m.id}"><span><span class="meta">MODULE ${m.number}</span><br><strong>${esc(m.title)}</strong></span><span class="meta">${moduleProgress(m)}% →</span></a>`).join('')}</div><a class="button text" href="#/course">VIEW ALL MODULES <span>→</span></a></section><section class="dash-section"><h2>RECENT FEEDBACK</h2>${fb?`<div class="simple-list"><div class="simple-row"><span><span class="meta">${esc(submission.assignment)} · ${esc(fb.status||'REVIEWED')}</span><br><strong>${esc(fb.text||'Your work has been reviewed.')}</strong></span></div></div><a class="button text" href="#/assignment">VIEW SUBMISSION <span>→</span></a>`:`<div class="empty"><span class="eyebrow">NO FEEDBACK YET</span><p>Your instructor's notes will appear here after your work has been reviewed.</p></div>`}</section></div><section class="dash-section" style="margin-top:42px"><div class="simple-row"><span><span class="meta">WHAT'S NEW · SEPTEMBER 2026</span><br><strong>A living elective. New cases and perspectives will continue to be added to this edition.</strong></span><a class="button text" href="#/updates">VIEW UPDATES →</a></div></section><div class="dash-lower"><section class="dash-section"><h2>FINAL PROJECT</h2><div class="empty"><span class="eyebrow">${pct()===100?'READY TO SHARE':'YOUR FINAL CHALLENGE'}</span><p>Design the hospitality concept of tomorrow. Your concept work can develop throughout the elective.</p><a class="button text" href="#/assignment">OPEN THE BRIEF →</a></div></section><section class="dash-section"><h2>COURSE STATUS</h2><div class="simple-list"><div class="simple-row"><span class="meta">EDITION</span><strong>${C.edition} · ACTIVE</strong></div><div class="simple-row"><span class="meta">INSTITUTION</span><strong>Hotel Institute Montreux</strong></div><div class="simple-row"><span class="meta">CERTIFICATE</span><strong>${certificateReady()?'<a href="#/certificate">READY TO ISSUE ↗</a>':'FINAL REVIEW PENDING'}</strong></div></div></section></div></main>${bottomNav()}`);}
  function coursePage(){return layout(`<main class="app-main"><div class="page-head"><div><span class="eyebrow">THE DIGITAL ELECTIVE · ${C.edition} EDITION</span><h1 class="page-title">THE FUTURE<br>OF HOSPITALITY</h1><p>${C.descriptor}</p><div class="course-meta"><div><strong>9</strong><span>Modules</span></div><div><strong>12 weeks</strong><span>Suggested pace</span></div><div><strong>${pct()}%</strong><span>Completed</span></div><div><strong>English</strong><span>Language</span></div></div></div>${button('CONTINUE',`lesson/${(allLessons.find(x=>!progressFor().includes(x.id))||allLessons[0]).module.id}/${(allLessons.find(x=>!progressFor().includes(x.id))||allLessons[0]).id}`)}</div>${image('horeca-interior-sconces.jpg','Atmospheric contemporary hospitality interior','course-hero-image')}<div class="section-head"><div><span class="eyebrow">YOUR LEARNING JOURNEY</span><h2 style="font-size:48px">Explore the modules.</h2></div><p>Move at your own pace. Each module brings together a focused lesson, an industry case and a challenge to apply your thinking.</p></div><div class="app-module-list">${C.modules.map(m=>`<a class="app-module" href="#/module/${m.id}"><span class="module-num">${m.number}</span><div><h3>${esc(m.title)}</h3><p>${esc(m.description)}</p></div><div class="progress-holder"><div class="bar"><span style="width:${moduleProgress(m)}%"></span></div></div><span class="progress-cell">${moduleProgress(m)}% · ${m.lessons.length} LESSON</span><span>↗</span></a>`).join('')}</div></main>${bottomNav()}`);}
  function modulePage(id){const m=C.modules.find(x=>x.id===id);if(!m)return notFound();const l=m.lessons[0];return layout(`<main class="app-main"><div class="crumb"><a href="#/course">THE ELECTIVE</a> / MODULE ${m.number}</div><div class="module-detail"><div><span class="eyebrow">MODULE ${m.number} · ${moduleProgress(m)}% COMPLETE</span><h2>${esc(m.title)}</h2><p>${esc(m.description)}</p><div class="bar" style="max-width:360px;margin:20px 0"><span style="width:${moduleProgress(m)}%"></span></div><span class="meta">${m.lessons.length} LEARNING UNIT · ${l.duration}</span><div class="lesson-list">${m.lessons.map(x=>`<a class="lesson-link" href="#/lesson/${m.id}/${x.id}"><span class="meta">${progressFor().includes(x.id)?'<span class="done">✓</span>':'→'}</span><strong>${esc(x.title)}</strong><span class="meta">${x.duration}</span></a>`).join('')}</div><div class="case-inline"><span class="meta">INDUSTRY CASE</span><h3>${esc(l.case)}</h3><p>Examine the choices behind the experience, and what they reveal about contemporary hospitality.</p><a class="button text" href="#/cases">OPEN CASE FILES →</a></div></div><div>${image(m.image,`${m.title} editorial feature image`,'module-photo')}<span class="eyebrow" style="margin-top:20px">LEARNING OBJECTIVES</span><ul class="objective-list">${l.ideas.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><blockquote class="case-quote">“${esc(l.intro)}”</blockquote></div></div><div class="lesson-footer"><a class="button text" href="#/course">← ALL MODULES</a>${button('START MODULE',`lesson/${m.id}/${l.id}`)}</div></main>${bottomNav()}`);}
  function lessonPage(mid,lid){const m=C.modules.find(x=>x.id===mid),l=m?.lessons.find(x=>x.id===lid);if(!l)return notFound();const i=allLessons.findIndex(x=>x.id===lid),next=allLessons[i+1];const done=progressFor().includes(l.id);return layout(`<main class="app-main"><article class="lesson-layout"><div class="crumb"><a href="#/course">THE ELECTIVE</a> / <a href="#/module/${m.id}">MODULE ${m.number}</a> / LESSON ${String(i+1).padStart(2,'0')}</div><div class="lesson-heading"><div><span class="eyebrow">MODULE ${m.number} · ${esc(m.title)}</span><h1>${esc(l.title)}</h1><p>${esc(l.intro)}</p></div><div class="lesson-number"><span class="meta">LESSON ${String(i+1).padStart(2,'0')}</span><br><span class="meta">${l.duration.toUpperCase()}</span></div></div><section class="video-frame" aria-label="Lesson media"><div>${l.videoUrl?`<video controls playsinline preload="metadata" poster="${ASSET}${esc(l.thumbnail)}" src="${esc(l.videoUrl)}" data-video-lesson="${esc(l.id)}" aria-label="${esc(l.title)} lesson film"></video>`:image(l.thumbnail,`${l.title} visual`)}</div><div class="video-info"><span class="eyebrow">${l.videoUrl?'LESSON FILM':'EDITORIAL LESSON'} · ${l.duration.toUpperCase()}</span><h2>${esc(l.title)}</h2><p>${l.videoUrl?'Watch the lesson film, then explore the reading, case and challenge below.':'This edition’s lesson film is being prepared. Explore the editorial reading and key ideas below, then mark the lesson complete when you’re ready.'}</p><div class="video-status"><span class="meta">${done?'LESSON COMPLETED':l.videoUrl?'PLAY · PAUSE · FULLSCREEN':'READING · CASE · CHALLENGE'}</span></div></div></section><div class="content-columns"><section><span class="eyebrow">THE IDEA</span><h2>Look beyond the surface.</h2><p>${esc(l.body)}</p><p>${esc(l.intro)}</p><div class="case-inline"><span class="meta">CASE STUDY · ${esc(l.case)}</span><h3>Why this case matters</h3><p>Consider the relationship between a clear point of view and the details that make it tangible for guests and teams.</p><a class="button text" href="#/cases">EXPLORE CASE STUDIES →</a></div></section><aside><span class="eyebrow">KEY IDEAS</span><ul class="key-ideas">${l.ideas.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><div class="case-inline"><span class="meta">READ MORE</span><p>Use the course case files and references as a starting point for your own investigation. Bring a specific observation to your next discussion.</p></div></aside></div><section class="challenge-panel"><div><span class="eyebrow">YOUR CHALLENGE</span><p>${esc(l.challenge)}</p></div><a href="#/assignment" class="button light">OPEN THE BRIEF <span>↗</span></a></section><div class="lesson-footer"><a class="button text" href="#/module/${m.id}">← MODULE ${m.number}</a><div style="display:flex;gap:14px;align-items:center">${done?'<span class="status-pill">COMPLETED</span>':`<button class="button light" data-action="complete" data-lesson="${l.id}">MARK AS COMPLETE <span>✓</span></button>`}${next?`<a href="#/lesson/${next.module.id}/${next.id}" class="button">NEXT LESSON <span>→</span></a>`:'<a href="#/certificate" class="button">FINISH THE ELECTIVE <span>→</span></a>'}</div></div></article></main>${bottomNav()}`);}
  function casesPage(){return layout(`<main class="app-main"><div class="page-head"><div><span class="eyebrow">INDUSTRY NOTEBOOK · 2026 EDITION</span><h1 class="page-title">REAL INDUSTRY.<br>USEFUL QUESTIONS.</h1><p>Case files connect hospitality practice to the ideas in this elective. Read closely, then decide what is relevant to the concept you want to build.</p></div><button class="button light" data-action="search">SEARCH THE ELECTIVE <span>⌕</span></button></div><div style="margin-top:32px">${C.cases.map((x,i)=>`<article class="case-feature" style="margin-bottom:24px;grid-template-columns:${i%2?'0.8fr 1.2fr':'1.2fr .8fr'}">${i%2?`<div class="case-feature-copy"><span class="eyebrow">CASE FILE · ${esc(x.location)} · ${esc(x.year)}</span><h3>${esc(x.title)}</h3><span class="meta">${esc(x.industry)}</span><p><strong>Context</strong><br>${esc(x.context)}</p><p><strong>What happened</strong><br>${esc(x.what)}</p><p><strong>Why it matters</strong><br>${esc(x.why)}</p><p><strong>Key takeaway</strong><br>${esc(x.takeaway)}</p></div>${image(x.image,`${x.title} case image`)}`:`${image(x.image,`${x.title} case image`)}<div class="case-feature-copy"><span class="eyebrow">CASE FILE · ${esc(x.location)} · ${esc(x.year)}</span><h3>${esc(x.title)}</h3><span class="meta">${esc(x.industry)}</span><p><strong>Context</strong><br>${esc(x.context)}</p><p><strong>What happened</strong><br>${esc(x.what)}</p><p><strong>Why it matters</strong><br>${esc(x.why)}</p><p><strong>Key takeaway</strong><br>${esc(x.takeaway)}</p></div>`}</article>`).join('')}</div></main>${bottomNav()}`);}
  function assignmentPage(){const u=user();const mine=state.submissions.filter(s=>s.student===u.email&&s.courseId===C.id&&s.edition===C.edition).at(-1);return layout(`<main class="app-main"><div class="page-head"><div><span class="eyebrow">APPLY YOUR THINKING · FINAL CHALLENGE</span><h1 class="page-title">DESIGN THE<br>HOSPITALITY CONCEPT<br>OF TOMORROW.</h1><p>Imagine you are building a hospitality concept for 2030. Bring the course into a clear, considered proposition.</p></div><span class="edition-tag meta">SUBMISSION · ${mine&&sessionStorage.getItem('chs-revising')==='1'?'REVISION IN PROGRESS':mine?esc(mine.status):'OPEN'}</span></div><div class="assignment-layout" style="margin-top:38px"><section class="assignment-brief"><span class="eyebrow">THE BRIEF</span><h2>Make the future tangible.</h2><p>Develop a concept that connects a distinct audience and occasion to an experience your team can credibly deliver.</p><span class="meta">YOUR CONCEPT SHOULD INCLUDE</span><ul><li>Concept and target audience</li><li>Guest experience and journey</li><li>Space and visual direction</li><li>Food & beverage proposition</li><li>Technology choices and human touchpoints</li><li>Business model and operating logic</li></ul><span class="meta">SUBMISSION FORMAT</span><p>Write your concept here and attach a PDF, image or presentation. You may also include a link to your work.</p><span class="meta">REVIEW</span><p>Your instructor will provide human, editorial feedback. Work may be approved or returned for revision.</p></section><section><span class="eyebrow">YOUR SUBMISSION</span>${mine&&sessionStorage.getItem('chs-revising')!=='1'?`<div class="simple-list"><div class="simple-row"><span class="meta">STATUS</span><span class="status-pill">${esc(mine.status)}</span></div><div class="simple-row"><span class="meta">SUBMITTED</span><strong>${new Date(mine.date).toLocaleDateString()}</strong></div><div class="simple-row"><span class="meta">ATTACHMENTS</span><strong>${esc((mine.files||[]).join(', ')||'No files')}</strong></div></div><div class="review-work" style="margin:20px 0">${esc(mine.answer)}</div>${mine.feedback?`<div class="case-inline"><span class="meta">INSTRUCTOR FEEDBACK · SCORE ${esc(mine.feedback.score??'—')}</span><p>${esc(mine.feedback.text)}</p></div>`:''}${mine.status==='REVISION REQUESTED'?'<button class="button light" data-action="revise">RESUBMIT REVISION <span>↗</span></button>':''}`:`<form id="assignment-form"><div class="field"><label for="answer">Concept note</label><textarea class="form-control" id="answer" name="answer" rows="9" required placeholder="What are you building, for whom, and why does it matter?">${esc(sessionStorage.getItem('chs-revising')==='1'?mine?.answer||'':'')}</textarea></div><div class="field"><label for="link">Link to your presentation (optional)</label><input class="form-control" id="link" name="link" type="url" value="${esc(sessionStorage.getItem('chs-revising')==='1'?mine?.link||'':'')}" placeholder="https://"></div><div class="field"><label>Attach supporting files</label><div class="file-drop"><label class="meta" for="files">PDF · IMAGE · PRESENTATION · UP TO 15 MB EACH</label><br><input type="file" name="files" id="files" accept=".pdf,.png,.jpg,.jpeg,.ppt,.pptx,.key" multiple><p class="form-help">Files are stored in this browser for the demo experience.</p></div></div><button class="button" type="submit">SUBMIT ASSIGNMENT <span>↗</span></button></form>`}</section></div></main>${bottomNav()}`);}
  function instructorPage(){const list=state.submissions.map((s,i)=>({...s,_index:i})).filter(s=>s.status!=='SUPERSEDED'&&s.institutionId===user()?.institutionId&&s.courseId===C.id&&s.edition===C.edition);const awaiting=list.filter(s=>s.status==='WAITING FOR REVIEW'||s.status==='REVISION REQUESTED');return layout(`<main class="app-main"><div class="welcome"><div><span class="eyebrow">INSTRUCTOR SPACE · HOTEL INSTITUTE MONTREUX</span><h1>COURSE<br>OVERVIEW.</h1><p>Review student work and return feedback that moves ideas forward.</p></div><span class="edition-tag meta">${C.edition} EDITION · ACTIVE</span></div><p class="form-help">Sample cohort snapshot for product demonstration; connect live analytics before institutional use.</p><div class="metric-grid"><div class="metric"><span>Total students</span><strong>24</strong></div><div class="metric"><span>Active this week</span><strong>18</strong></div><div class="metric"><span>Average progress</span><strong>${list.length?Math.round(pct()):42}%</strong></div><div class="metric"><span>Awaiting review</span><strong>${awaiting.length}</strong></div></div><section id="submissions"><div class="page-head" style="padding-top:25px"><div><span class="eyebrow">STUDENT WORK</span><h2 class="page-title" style="font-size:48px">SUBMISSIONS</h2><p>Review work for the 2026 edition. Student submissions remain edition-scoped.</p></div></div>${list.length?`<div class="submission-row" style="border-bottom:1px solid var(--ink)"><span class="meta">STUDENT</span><span class="meta">ASSIGNMENT</span><span class="meta">SUBMITTED</span><span class="meta">STATUS</span></div>${list.map(s=>`<a class="submission-row" href="#/review/${s._index}"><strong>${esc(s.name)}</strong><span>${esc(s.assignment)}</span><span class="meta">${new Date(s.date).toLocaleDateString()}</span><span class="status-pill">${esc(s.status)}</span></a>`).join('')}`:`<div class="empty"><span class="eyebrow">NO SUBMISSIONS YET</span><p>Student work will appear here when it is submitted for review.</p><p>To test the complete flow, sign in as the demo student, submit the final challenge, then return here as the instructor.</p></div>`}</section><div class="dash-lower" id="analytics"><section><h2 class="serif">Module performance</h2><p class="form-help">Illustrative overview for this demo edition.</p><div class="chart-bars">${[76,62,54,68,45,36,51,29,8].map((n,i)=>`<div style="height:${n}%"><span>${String(i+1).padStart(2,'0')}</span></div>`).join('')}</div></section><section><h2 class="serif">Recent activity</h2><div class="empty">${list.length?`${list.length} submission${list.length>1?'s':''} in this edition.`:'Course activity will appear as learners progress through the edition.'}</div></section></div></main>${bottomNav()}`);}
  function reviewPage(index){const s=state.submissions[Number(index)];if(!s||s.institutionId!==user()?.institutionId||s.courseId!==C.id||s.edition!==C.edition)return notFound();return layout(`<main class="app-main"><div class="crumb"><a href="#/instructor">SUBMISSIONS</a> / REVIEW</div><div class="page-head"><div><span class="eyebrow">INSTRUCTOR REVIEW · ${C.edition} EDITION</span><h1 class="page-title">${esc(s.name).toUpperCase()}</h1><p>${esc(s.assignment)} · Submitted ${new Date(s.date).toLocaleString()}</p></div><span class="status-pill">${esc(s.status)}</span></div><div class="submission-review"><section><span class="eyebrow">STUDENT WORK</span><div class="review-work">${esc(s.answer)}${s.link?`\n\nLINK: ${esc(s.link)}`:''}</div><div class="simple-list">${(s.files||[]).map((f,i)=>`<div class="simple-row"><strong>${esc(f)}</strong><a class="button text" href="#" data-action="download-file" data-submission="${s.id}" data-index="${i}">DOWNLOAD →</a></div>`).join('')||'<div class="empty">No files attached.</div>'}</div></section><form id="review-form" data-id="${s.id}" class="review-actions"><span class="eyebrow">EDITORIAL FEEDBACK</span><div class="field"><label for="feedback">Notes for the student</label><textarea class="form-control" id="feedback" rows="9" required placeholder="What is working? What would strengthen the concept next?">${esc(s.feedback?.text||'')}</textarea></div><div class="field"><label for="score">Score (optional)</label><input class="form-control" id="score" type="number" min="0" max="100" value="${esc(s.feedback?.score??'')}" placeholder="0–100"></div><div style="display:flex;gap:10px;flex-wrap:wrap"><button class="button" name="decision" value="APPROVED" type="submit">APPROVE WORK <span>✓</span></button><button class="button light" name="decision" value="REVISION REQUESTED" type="submit">REQUEST REVISION <span>↗</span></button></div></form></div></main>${bottomNav()}`);}
  function progressPage(){return layout(`<main class="app-main"><div class="page-head"><div><span class="eyebrow">YOUR LEARNING RECORD · ${C.edition} EDITION</span><h1 class="page-title">PROGRESS,<br>WITH PURPOSE.</h1><p>A clear view of the ideas explored, challenges submitted and milestones ahead.</p></div><div class="progress-ring" style="color:var(--ink);border-color:var(--line)"><span>${pct()}%<small style="color:var(--muted)">COMPLETE</small></span></div></div><div class="metric-grid"><div class="metric"><span>Lessons completed</span><strong>${completeCount()}</strong></div><div class="metric"><span>Quiz results</span><strong>${Object.keys(state.quizzes).filter(k=>k.startsWith(key())).length}</strong></div><div class="metric"><span>Assignments</span><strong>${state.submissions.filter(s=>s.student===user().email).length}</strong></div><div class="metric"><span>Certificate</span><strong style="font-size:22px">${pct()===100?'READY':'IN PROGRESS'}</strong></div></div><div class="app-module-list">${C.modules.map(m=>`<a class="app-module" href="#/module/${m.id}"><span class="module-num">${m.number}</span><div><h3>${esc(m.title)}</h3><p>${m.lessons.filter(l=>progressFor().includes(l.id)).length} of ${m.lessons.length} learning unit completed</p></div><div class="progress-holder"><div class="bar"><span style="width:${moduleProgress(m)}%"></span></div></div><span class="progress-cell">${moduleProgress(m)}%</span><span>↗</span></a>`).join('')}</div><div class="lesson-footer"><a href="#/quiz" class="button light">TAKE A KNOWLEDGE CHECK <span>↗</span></a>${pct()===100?button('VIEW CERTIFICATE','certificate'):''}</div></main>${bottomNav()}`);}
  function quizPage(){const qkey=`${key()}:quiz01`;const old=state.quizzes[qkey];return layout(`<main class="app-main"><div class="page-head"><div><span class="eyebrow">KNOWLEDGE CHECK · MODULE 05</span><h1 class="page-title">AUTOMATION<br>WITHOUT LOSING<br>HUMANITY.</h1><p>One question to pause and apply your thinking.</p></div><span class="edition-tag meta">QUESTION 01 / 01</span></div>${old?`<section class="institution-panel"><span class="eyebrow">RESULT · ${old.score===1?'CORRECT':'REVIEW'}</span><h2>${old.score===1?'A useful distinction.':'Return to the key idea.'}</h2><p>Automation can remove friction, but the value of hospitality often lives in human attention and judgement.</p><button class="button light" data-action="retake-quiz">TRY AGAIN <span>↻</span></button></section>`:`<form id="quiz-form" class="institution-panel"><span class="meta">QUESTION 01</span><h2>Which principle best guides automation in a hospitality setting?</h2><label class="simple-row" style="justify-content:flex-start"><input type="radio" name="answer" value="a" required> Automate every guest interaction to maximise speed.</label><label class="simple-row" style="justify-content:flex-start"><input type="radio" name="answer" value="b"> Automate repetition while protecting moments where human attention creates value.</label><label class="simple-row" style="justify-content:flex-start"><input type="radio" name="answer" value="c"> Use technology only when guests can see it working.</label><button class="button" style="margin-top:24px" type="submit">SUBMIT ANSWER <span>↗</span></button></form>`}</main>${bottomNav()}`);}
  function certificatePage(){const u=user();const id=`HIM-${C.edition}-${String(Math.abs((u.email+C.edition).split('').reduce((a,c)=>a+c.charCodeAt(0),0))).padStart(6,'0')}`;return layout(`<main class="app-main"><div class="page-head"><div><span class="eyebrow">A MILESTONE WORTH SHARING</span><h1 class="page-title">YOUR CERTIFICATE.</h1><p>This printable certificate is issued when all lessons are complete and your final project is approved.</p></div><button class="button" data-action="print" ${certificateReady()?'':'disabled'}>DOWNLOAD / PRINT <span>↗</span></button></div>${certificateReady()?`<section class="certificate"><span class="eyebrow">HIM × EGOR TARASENKO</span><span class="meta">THE FUTURE OF HOSPITALITY</span><h1>Certificate of<br>Completion</h1><p>This certificate confirms that</p><div class="cert-name">${esc(u.name)}</div><p>has successfully completed the digital elective.</p><span class="meta">${C.edition} EDITION</span><div class="certificate-footer"><span class="meta">CERTIFICATE ID · ${id}</span><span class="meta">ISSUED · ${new Date().toLocaleDateString()}</span></div></section>`:`<div class="empty"><span class="eyebrow">IN PROGRESS · ${pct()}% COMPLETE</span><p>Complete all nine lessons and receive approval for your final project to make the certificate available. Your progress is saved for this edition.</p><a class="button" href="#/course">RETURN TO THE ELECTIVE <span>↗</span></a></div>`}</main>${bottomNav()}`);}
  function adminPage(){return layout(`<main class="app-main"><div class="welcome"><div><span class="eyebrow">PLATFORM ADMINISTRATION · MULTI-INSTITUTION</span><h1>INSTITUTIONS<br>& EDITIONS.</h1><p>Manage access across institutions without tying the course to a single school.</p></div><span class="edition-tag meta">ADMINISTRATOR</span></div><div class="metric-grid"><div class="metric"><span>Institutions</span><strong>01</strong></div><div class="metric"><span>Active licenses</span><strong>${state.licenseActive?'01':'00'}</strong></div><div class="metric"><span>Licensed students</span><strong>24 / 100</strong></div><div class="metric"><span>Active edition</span><strong>${C.edition}</strong></div></div><section id="institutions" class="institution-panel"><span class="eyebrow">INSTITUTION · HIM-001</span><h2>Hotel Institute Montreux</h2><p>The Future of Hospitality · ${C.edition} Edition</p><div class="simple-list"><div class="simple-row"><span class="meta">LICENSE PERIOD</span><strong>01.09.2026 — 31.08.2027</strong></div><div class="simple-row"><span class="meta">STUDENT LIMIT</span><strong>24 / 100</strong></div><div class="simple-row"><span class="meta">STATUS</span><span class="status-pill">${state.licenseActive?'ACTIVE':'SUSPENDED'}</span></div><div class="simple-row"><span class="meta">CONTENT OWNERSHIP</span><strong>Author-owned · institution access by license</strong></div></div><button class="button light" data-action="toggle-license" style="margin-top:22px">${state.licenseActive?'SUSPEND DEMO LICENSE':'REACTIVATE DEMO LICENSE'} <span>↻</span></button></section><div class="dash-lower" id="analytics"><section><h2 class="serif">Course editions</h2><div class="simple-list"><div class="simple-row"><span><strong>2026 Edition</strong><br><span class="meta">ACTIVE · HIM</span></span><span class="status-pill">CURRENT</span></div><div class="simple-row"><span><strong>2027 Edition</strong><br><span class="meta">CONTENT PLANNING</span></span><span class="meta">FUTURE</span></div><div class="simple-row"><span><strong>2028 Edition</strong><br><span class="meta">NOT STARTED</span></span><span class="meta">FUTURE</span></div></div></section><section><h2 class="serif">Platform architecture</h2><p class="form-help">Institution · User · Course · Edition · Module · Lesson · Submission · Feedback · Progress · License · Enrollment · Certificate</p><div class="empty">Edition-scoped progress and assessment records preserve student work when course content evolves.</div></section></div></main>${bottomNav()}`);}
  function profilePage(){const u=user();return layout(`<main class="app-main"><div class="page-head"><div><span class="eyebrow">YOUR ACCOUNT · STUDENT PROFILE</span><h1 class="page-title">${esc(u.name).toUpperCase()}.</h1><p>Your learning profile for this institution and edition.</p></div><span class="avatar" style="width:58px;height:58px;font-size:16px">${initials(u.name)}</span></div><section class="institution-panel"><span class="eyebrow">PROFILE DETAILS</span><div class="simple-list"><div class="simple-row"><span class="meta">NAME</span><strong>${esc(u.name)}</strong></div><div class="simple-row"><span class="meta">EMAIL</span><strong>${esc(u.email)}</strong></div><div class="simple-row"><span class="meta">ROLE</span><strong>${esc(u.role)}</strong></div><div class="simple-row"><span class="meta">INSTITUTION</span><strong>Hotel Institute Montreux</strong></div><div class="simple-row"><span class="meta">ENROLLED EDITION</span><strong>${C.edition} · THE FUTURE OF HOSPITALITY</strong></div></div><button class="button light" data-action="logout" style="margin-top:24px">SIGN OUT <span>↗</span></button></section></main>${bottomNav()}`)}
  function updatesPage(){return layout(`<main class="app-main"><div class="page-head"><div><span class="eyebrow">WHAT'S NEW · A LIVING ELECTIVE</span><h1 class="page-title">THE INDUSTRY<br>KEEPS MOVING.</h1><p>Course editions are designed to evolve with hospitality. New materials can be added while preserving past learning records.</p></div></div>${C.updates.map(x=>`<article class="institution-panel"><span class="eyebrow">${esc(x.tag)} · ${esc(x.date)}</span><h2>${esc(x.title)}</h2><p>${esc(x.text)}</p></article>`).join('')}</main>${bottomNav()}`);}
  function searchPage(query=''){const q=query.toLowerCase();const results=[];C.modules.forEach(m=>{if(`${m.title} ${m.description}`.toLowerCase().includes(q))results.push({type:'MODULE',title:m.title,desc:m.description,href:`module/${m.id}`});m.lessons.forEach(l=>{if(`${l.title} ${l.intro} ${l.body}`.toLowerCase().includes(q))results.push({type:'LESSON',title:l.title,desc:l.intro,href:`lesson/${m.id}/${l.id}`})})});C.cases.forEach(x=>{if(`${x.title} ${x.location} ${x.context} ${x.takeaway}`.toLowerCase().includes(q))results.push({type:'CASE STUDY',title:x.title,desc:x.context,href:'cases'})});return layout(`<main class="app-main"><div class="page-head"><div><span class="eyebrow">GLOBAL SEARCH · EDUCATIONAL CONTENT</span><h1 class="page-title">FIND A THREAD.</h1></div></div><form id="search-form" style="display:flex;gap:10px;margin:26px 0"><input class="form-control" name="q" value="${esc(query)}" placeholder="Search lessons, modules, cases and topics" aria-label="Search course content"><button class="button">SEARCH <span>⌕</span></button></form>${query?results.length?`<span class="eyebrow">${results.length} RESULT${results.length===1?'':'S'} FOR “${esc(query)}”</span><div class="simple-list">${results.map(r=>`<a class="simple-row" href="#/${r.href}"><span><span class="meta">${r.type}</span><br><strong>${esc(r.title)}</strong><br><span class="form-help">${esc(r.desc)}</span></span><span>↗</span></a>`).join('')}</div>`:`<div class="empty"><span class="eyebrow">NO RESULTS</span><p>No content matched that search. Try a broader topic.</p></div>`:`<div class="empty"><span class="eyebrow">SEARCH THE EDITION</span><p>Find a lesson, module, case or topic across the course.</p></div>`}</main>${bottomNav()}`);}
  function notFound(){return layout(`<main class="app-main"><div class="page-head"><div><span class="eyebrow">404 · PAGE NOT FOUND</span><h1 class="page-title">NOT THIS WAY.</h1><p>The page may have moved or may not be part of this edition.</p></div>${button('RETURN TO THE ELECTIVE',user()?'dashboard':'')}</div></main>`);}
  function render(){state=getState();syncTelegramNavigation();const r=route();const u=user();if(r[0]==='login'){app.innerHTML=login();return}if(!r[0]){app.innerHTML=landing();return}if(!u){location.hash='/login';return}if(!state.licenseActive && u.role==='STUDENT'&&!['expired','logout'].includes(r[0])){app.innerHTML=layout(`<main class="app-main"><div class="page-head"><div><span class="eyebrow">ACCESS · LICENSE STATUS</span><h1 class="page-title">THIS EDITION<br>IS UNAVAILABLE.</h1><p>Your institution's course license is not active. Contact your course administrator for support.</p></div></div></main>`);return}
    if(r[0]==='dashboard'&&u.role==='STUDENT')app.innerHTML=dashboard();else if(r[0]==='course')app.innerHTML=coursePage();else if(r[0]==='module')app.innerHTML=modulePage(r[1]);else if(r[0]==='lesson')app.innerHTML=lessonPage(r[1],r[2]);else if(r[0]==='cases')app.innerHTML=casesPage();else if(r[0]==='assignment')app.innerHTML=assignmentPage();else if(r[0]==='instructor'&&u.role==='INSTRUCTOR')app.innerHTML=instructorPage();else if(r[0]==='review'&&u.role==='INSTRUCTOR')app.innerHTML=reviewPage(r[1]);else if(r[0]==='progress')app.innerHTML=progressPage();else if(r[0]==='quiz')app.innerHTML=quizPage();else if(r[0]==='certificate')app.innerHTML=certificatePage();else if(r[0]==='admin'&&u.role==='ADMIN')app.innerHTML=adminPage();else if(r[0]==='updates')app.innerHTML=updatesPage();else if(r[0]==='profile')app.innerHTML=profilePage();else if(r[0]==='search')app.innerHTML=searchPage(new URLSearchParams(location.hash.split('?')[1]||'').get('q')||'');else if(r[0]==='logout'){sessionStorage.removeItem('chs-user');go('');}else app.innerHTML=u.role==='STUDENT'?notFound():`<main class="app-main"><div class="page-head"><div><span class="eyebrow">403 · ACCESS RESTRICTED</span><h1 class="page-title">THIS SPACE<br>IS ROLE-RESTRICTED.</h1><p>Your current role does not have access to this area.</p></div><a class="button" href="#/${u.role==='INSTRUCTOR'?'instructor':u.role==='ADMIN'?'admin':'dashboard'}">RETURN TO YOUR SPACE <span>↗</span></a></div></main>`;
  }
  function toast(text){const t=document.getElementById('toast');t.textContent=text;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2600)}
  function updateProgress(id){state=getState();const list=state.progress[key()]||[];if(!list.includes(id)){list.push(id);state.progress[key()]=list;saveState(state);toast('LESSON COMPLETED · PROGRESS SAVED')}render()}
  function openSearch(){const q=prompt('Search lessons, modules, cases and topics');if(q?.trim())go(`search?q=${encodeURIComponent(q.trim())}`)}
  function idbFile(submissionId,index){return new Promise((resolve,reject)=>{const req=indexedDB.open('chs-submission-files',1);req.onupgradeneeded=()=>req.result.createObjectStore('files');req.onsuccess=()=>{const db=req.result;const tx=db.transaction('files','readonly');const get=tx.objectStore('files').get(`${submissionId}:${index}`);get.onsuccess=()=>resolve(get.result);get.onerror=()=>reject(get.error)};req.onerror=()=>reject(req.error)})}
  document.addEventListener('click', async e=>{
    const role=e.target.closest('[data-role]');if(role){demoUser(role.dataset.role);return}
    const action=e.target.closest('[data-action]')?.dataset.action;
    if(action==='complete'){updateProgress(e.target.closest('[data-action]').dataset.lesson);return}
    if(action==='search'){e.preventDefault();openSearch();return}
    if(action==='profile'){go('profile');return}if(action==='logout'){if(confirm('Sign out of this demo profile?'))go('logout');return}
    if(action==='retake-quiz'){state=getState();delete state.quizzes[`${key()}:quiz01`];saveState(state);render();return}
    if(action==='print'){window.print();return}
    if(action==='toggle-license'){state=getState();state.licenseActive=!state.licenseActive;state.licenses[0].status=state.licenseActive?'ACTIVE':'SUSPENDED';saveState(state);render();toast(`DEMO LICENSE ${state.licenseActive?'ACTIVE':'SUSPENDED'}`);return}
    if(action==='revise'){state=getState();const prior=state.submissions.filter(s=>s.student===user().email&&s.courseId===C.id&&s.edition===C.edition).at(-1);if(prior)prior.status='SUPERSEDED';sessionStorage.setItem('chs-revising','1');saveState(state);render();return}
    if(action==='download-file'){e.preventDefault();const el=e.target.closest('[data-action]');try{const file=await idbFile(el.dataset.submission,Number(el.dataset.index));if(!file){toast('FILE IS NOT AVAILABLE IN THIS BROWSER');return}const url=URL.createObjectURL(file.blob);const a=document.createElement('a');a.href=url;a.download=file.name;a.click();URL.revokeObjectURL(url)}catch{toast('FILE STORAGE IS NOT AVAILABLE')};return}
    if(e.target.closest('[data-scroll]')){const dest=e.target.closest('[data-scroll]').dataset.scroll;setTimeout(()=>document.getElementById(dest)?.scrollIntoView({behavior:'smooth'}),50)}
  });
  document.addEventListener('ended',e=>{if(e.target.matches('video[data-video-lesson]'))updateProgress(e.target.dataset.videoLesson)},true);
  document.addEventListener('submit',async e=>{
    e.preventDefault();
    if(e.target.id==='login-form'){const d=new FormData(e.target),email=String(d.get('email')).trim().toLowerCase(),pass=String(d.get('password'));if(!email||pass.length<1){document.getElementById('login-error').textContent='Enter your email and password.';return}let role='STUDENT',name=email.split('@')[0].split(/[._-]/).map(x=>x[0]?.toUpperCase()+x.slice(1)).join(' ');if(email==='instructor@him.edu'){role='INSTRUCTOR';name='Egor Tarasenko'}if(email==='admin@him.edu'){role='ADMIN';name='HIM Administrator'}if(email==='student@him.edu'){role='STUDENT';name='Alex Morgan'}const profile={email,name,role,institutionId:'him-001'};sessionStorage.setItem('chs-user',JSON.stringify(profile));ensureEnrollment(profile);go(role==='STUDENT'?'dashboard':role==='INSTRUCTOR'?'instructor':'admin');return}
    if(e.target.id==='assignment-form'){const u=user(),fd=new FormData(e.target),files=[...document.getElementById('files').files];if(files.some(f=>f.size>15*1024*1024)){toast('EACH FILE MUST BE UNDER 15 MB');return}const sub={id:`sub-${Date.now()}`,student:u.email,institutionId:u.institutionId||'him-001',courseId:C.id,edition:C.edition,assignment:'Final Challenge · Design the hospitality concept of tomorrow',answer:String(fd.get('answer')||''),link:String(fd.get('link')||''),files:files.map(f=>f.name),date:new Date().toISOString(),status:'WAITING FOR REVIEW',feedback:null};
      try{if(files.length){await new Promise((resolve,reject)=>{const req=indexedDB.open('chs-submission-files',1);req.onupgradeneeded=()=>req.result.createObjectStore('files');req.onsuccess=()=>{const db=req.result,tx=db.transaction('files','readwrite');files.forEach((f,i)=>tx.objectStore('files').put({name:f.name,blob:f},`${sub.id}:${i}`));tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)};req.onerror=()=>reject(req.error)})}}catch{toast('FILE STORAGE FAILED — PLEASE TRY AGAIN');return}state=getState();state.submissions=state.submissions.filter(s=>s.student!==u.email);state.submissions.push(sub);sessionStorage.removeItem('chs-revising');saveState(state);toast('SUBMISSION RECEIVED');render();return}
    if(e.target.id==='review-form'){const form=e.target,id=form.dataset.id,decision=e.submitter?.value||'APPROVED';state=getState();const sub=state.submissions.find(s=>s.id===id);if(!sub)return;sub.status=decision;sub.feedback={text:document.getElementById('feedback').value,score:document.getElementById('score').value||null,status:decision,updatedAt:new Date().toISOString()};saveState(state);toast(decision==='APPROVED'?'FEEDBACK SAVED · WORK APPROVED':'FEEDBACK SAVED · REVISION REQUESTED');go('instructor');return}
    if(e.target.id==='quiz-form'){const val=new FormData(e.target).get('answer');state=getState();state.quizzes[`${key()}:quiz01`]={score:val==='b'?1:0,answer:val,at:new Date().toISOString()};saveState(state);render();return}
    if(e.target.id==='search-form'){const q=new FormData(e.target).get('q');go(`search?q=${encodeURIComponent(q)}`);return}
  });
  async function authenticateTelegram(){if(!tg?.initData)return;try{const response=await fetch('/api/telegram-auth',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({initData:tg.initData})});const result=await response.json();if(!response.ok||!result.user)throw new Error(result.error||'Telegram sign-in failed');const profile={...result.user,email:`telegram-${result.user.id}`,telegramId:result.user.id};sessionStorage.setItem('chs-user',JSON.stringify(profile));ensureEnrollment(profile);go(profile.role==='ADMIN'?'admin':'dashboard')}catch(error){console.error('Telegram authentication failed:',error);sessionStorage.removeItem('chs-user');go('login')}}
  window.addEventListener('hashchange',render);
  window.addEventListener('DOMContentLoaded',render);
  if(document.readyState!=='loading')render();
  if(tg?.initData)authenticateTelegram();
})();
